poison-reverse.pseudocode:
INFINITY = 16  # RIP 무한대 메트릭

def build_update(table, out_iface, poison=True):
    # table: 목적지 → (메트릭, 학습 인터페이스)
    update = {}
    for dest, (metric, iface) in table.items():
        if iface == out_iface:  # 이 인터페이스로 배운 경로
            if poison:
                update[dest] = INFINITY  # 포이즌 리버스
            continue  # 단순 스플릿 호라이즌은 생략
        update[dest] = metric
    return update

poisson-process.pseudocode:
def poisson_arrivals(lam, horizon):
    t, times = 0.0, []
    while True:
        u = random_uniform(0, 1)
        t += -log(1 - u) / lam  # 지수분포 간격(평균 1/λ)
        if t > horizon:
            return times  # 개수 ~ Poisson(λ·horizon)
        times.append(t)

